const raw = $input.item.json.text.replace(/```json|```/g,'').trim();
const result = JSON.parse(raw);
const highCount = result.anomalies.filter(a => a.severity === 'high').length;
return [{ json: { ...result, has_high_anomalies: highCount > 0, high_count: highCount } }];

